values.content:
=Bạn là biên tập viên website cho Eggu Sandwich. Từ bài đăng TikTok sau:
- Tiêu đề gốc: {{ $json.title }}
- Link video: {{ $json.link }}

Hãy tạo 1 bài viết ngắn cho website theo đúng định dạng JSON chuẩn (không bọc code markdown):
{
  "title": "Tiêu đề bài viết ngắn gọn dưới 70 ký tự",
  "slug": "duong-dan-bai-viet-khong-dau",
  "content": "Đoạn giới thiệu 100 từ về món ăn/sự kiện này kèm link video TikTok {{ $json.link }}"
}

parameters.jsCode:
const menuItems = [
  {
    name: "Bacon Double Cheese",
    category: "Bán chạy",
    usps: "Nhân đôi thịt xông khói áp chảo giòn thơm, đẫm phô mai Cheddar kép béo ngậy, trứng cuộn fluffy mềm mượt tan chảy",
    price: "49.000đ"
  },
  {
    name: "Mr. Egg",
    category: "Món chữ ký",
    usps: "Bánh mì brioche nướng bơ tỏi vàng rụm, trứng cuộn fluffy béo mịn, sốt sriracha ngọt béo cay nhẹ",
    price: "39.000đ"
  },
  {
    name: "Sandwich Bò Nướng Teriyaki",
    category: "Đặc biệt",
    usps: "Thịt bò mềm mọng sốt Teriyaki Nhật Bản mặn ngọt đậm đà, kết hợp trứng béo và phô mai thơm lừng",
    price: "55.000đ"
  },
  {
    name: "Sandwich Gà Giòn Sốt Cay",
    category: "Mới",
    usps: "Ức gà chiên xù giòn tan rụm, sốt cay Hàn Quốc đậm vị kết hợp phô mai béo ngậy cân bằng vị giác",
    price: "49.000đ"
  },
  {
    name: "Bánh Mì Nướng Bơ Tỏi Phô Mai",
    category: "Ăn nhẹ",
    usps: "Vỏ brioche nướng bơ tỏi Pháp giòn rụm bên ngoài, mềm xốp bên trong đẫm phô mai thơm nức mũi",
    price: "35.000đ"
  }
];

const today = new Date();
const dayOfWeek = today.getDay();

let angle = "";
if (dayOfWeek === 1 || dayOfWeek === 3) {
  angle = "Đồng hành công sở (Bữa sáng vội vã, ăn sạch tay, no lâu, gom đơn cùng đồng nghiệp)";
} else if (dayOfWeek === 2 || dayOfWeek === 4) {
  angle = "Cứu đói xế chiều 14h - 16h (Thèm phô mai kéo sợi ngập tràn, tiếp năng lượng giờ uể oải)";
} else if (dayOfWeek === 5) {
  angle = "Nạp năng lượng cuối tuần (Tự thưởng cho bản thân một bữa ăn chất lượng chuẩn vị Seoul)";
} else {
  angle = "Dạo phố cổ Hồ Gươm (Bánh nướng nóng hổi cầm tay dạo quanh phố 54 Nguyễn Hữu Huân)";
}

const selectedDish = menuItems[Math.floor(Math.random() * menuItems.length)];

return [
  {
    json: {
      dishName: selectedDish.name,
      dishCategory: selectedDish.category,
      dishUsps: selectedDish.usps,
      dishPrice: selectedDish.price,
      targetAngle: angle,
      date: today.toLocaleDateString("vi-VN"),
      storeAddress: "54 Nguyễn Hữu Huân, Hoàn Kiếm, Hà Nội",
      website: "eggu.vn"
    }
  }
];

let rawText = $json.content.parts[0].text.trim();
if (rawText.startsWith('```json')) {
  rawText = rawText.replace(/^```json/, '').replace(/```$/, '').trim();
} else if (rawText.startsWith('```')) {
  rawText = rawText.replace(/^```/, '').replace(/```$/, '').trim();
}

let parsed;
try {
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    title: 'Bài viết Facebook EGGU',
    content: rawText,
    dish: $('Code - Chọn Món & Góc Tiếp Cận').item.json.dishName,
    status: 'Chờ duyệt',
    created_at: new Date().toISOString()
  };
}

return [
  {
    json: {
      'Mã bài viết': 'FB-' + Date.now(),
      'Tiêu đề': parsed.title || 'Bài đăng EGGU',
      'Món ăn': parsed.dish || $('Code - Chọn Món & Góc Tiếp Cận').item.json.dishName,
      'Nội dung Facebook (Đã biên tập)': parsed.content || rawText,
      'Trạng thái': 'Chờ duyệt',
      'Thời gian tạo': parsed.created_at || new Date().toLocaleString('vi-VN'),
      'Kênh phê duyệt': 'Sẵn sàng đẩy sang Google Sheets hoặc Zalo OA'
    }
  }
];
